public class Vehicle { public static String MAKE="Augur"; public static int numVehicles=0; private String chassisNo,model; public Vehicle(String model){numVehicles++;chassisNo="ch"+numVehicles;this.model=model;System.out.println("Vehicle manufactured");} public String getChassisNo(){return chassisNo;} public void setChassisNo(String s){chassisNo=s;} public String getModel(){return model;} public void setModel(String m){model=m;} public static void setMake(String m){MAKE=m;} public String toString(){return "The vehicle is manufactured by: "+MAKE+"\nThe model type is "+model+"\nThe chassis number is "+chassisNo;} public static class Engine {private static final String MAKE="Predicter";private static final int CAPACITY=1600;public static String getMake(){return MAKE;}public static int getCapacity(){return CAPACITY;}}}
